import XCTest
final class ProbeTests:XCTestCase {
func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);var n=0;while !q.allElementsBoundByIndex.contains(where:{$0.isHittable}) && n<10{let e=q.firstMatch;let scroll=app.scrollViews.firstMatch;let up=e.frame.midY>=scroll.frame.minY+35;let from=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.72:0.35));let to=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.48:0.59));from.press(forDuration:0.1,thenDragTo:to);n+=1};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name+app.debugDescription);return};b.tap()}
func type(_ f:XCUIElement,_ value:String){f.tap();XCTAssertTrue(XCUIApplication(bundleIdentifier:"com.example.fancy.dev").keyboards.firstMatch.waitForExistence(timeout:10));for c in value{f.typeText(String(c));Thread.sleep(forTimeInterval:0.15)}}
func option(_ app:XCUIApplication,_ name:String){let q=app.otherElements.matching(NSPredicate(format:"label == %@",name));XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);let e=q.firstMatch;var n=0;while !e.isHittable && n<8{let scroll=app.scrollViews.firstMatch;let up=e.frame.midY>=scroll.frame.minY+35;let from=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.72:0.35));let to=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.48:0.59));from.press(forDuration:0.1,thenDragTo:to);n+=1};XCTAssertTrue(e.isHittable,app.debugDescription);e.tap()}
func shot(_ app:XCUIApplication,_ name:String){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
func selected(_ app:XCUIApplication,_ name:String)->Bool{let e=app.otherElements.matching(NSPredicate(format:"label == %@",name)).firstMatch;return e.exists && ((e.value as? String) ?? "").contains("Selected")}
func testNativeBystanderSurvey186() throws {continueAfterFailure=false;let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.terminate();app.launch();let decline=app.buttons["Decline analytics"];if decline.waitForExistence(timeout:5){decline.tap()};tap(app,"Profile, tab, 5 of 5");if app.staticTexts["QA Final Host"].firstMatch.waitForExistence(timeout:4){tap(app,"Settings");tap(app,"Sign out");tap(app,"Sign out");tap(app,"Profile, tab, 5 of 5")};if app.buttons["Sign in or create an account"].waitForExistence(timeout:4){tap(app,"Sign in or create an account")};tap(app,"Continue with email");let email=app.textFields["Email address"];XCTAssertTrue(email.waitForExistence(timeout:10));type(email,"p2b-bystander-85b20baf@example.invalid");tap(app,"Send code");let code=app.textFields["6-digit code"];XCTAssertTrue(code.waitForExistence(timeout:12),app.debugDescription);let ready=NSTemporaryDirectory()+"qa-j010-186-ready.json",reply=NSTemporaryDirectory()+"qa-j010-186-code.json";try? FileManager.default.removeItem(atPath:reply);try "{\"run\":186}".write(toFile:ready,atomically:true,encoding:.utf8);print("QA_J010_READY186="+ready);fflush(stdout);let until=Date().addingTimeInterval(150);while !FileManager.default.fileExists(atPath:reply) && Date()<until{Thread.sleep(forTimeInterval:0.2)};XCTAssertTrue(FileManager.default.fileExists(atPath:reply));let data=try Data(contentsOf:URL(fileURLWithPath:reply));let value=try JSONSerialization.jsonObject(with:data) as! [String:String];try FileManager.default.removeItem(atPath:reply);type(code,value["code"]!);tap(app,"Verify & continue");XCTAssertTrue(app.staticTexts["QA Final Bystander"].firstMatch.waitForExistence(timeout:12),app.debugDescription);shot(app,"native186-bystander-signed-in");tap(app,"Settings");tap(app,"Product survey");XCTAssertTrue(app.buttons["Update survey"].waitForExistence(timeout:12),app.debugDescription);print("QA_NATIVE186_SURVEY_LOADED\n"+app.debugDescription);XCTAssertTrue(selected(app,"No"),app.debugDescription);XCTAssertTrue(selected(app,"Cost"),app.debugDescription);shot(app,"native186-survey-prefilled-from-web");option(app,"Yes");option(app,"Restaurant");tap(app,"Update survey");XCTAssertTrue(app.staticTexts["Thank you. Your product survey is saved."].firstMatch.waitForExistence(timeout:12),app.debugDescription);shot(app,"native186-survey-updated");app.terminate();app.launch();tap(app,"Profile, tab, 5 of 5");tap(app,"Settings");tap(app,"Product survey");XCTAssertTrue(app.buttons["Update survey"].waitForExistence(timeout:12),app.debugDescription);XCTAssertTrue(selected(app,"Yes"),app.debugDescription);XCTAssertTrue(selected(app,"Restaurant"),app.debugDescription);XCTAssertTrue(selected(app,"Cost"),app.debugDescription);shot(app,"native186-survey-persisted-relaunch");print("QA_NATIVE186_SURVEY_PASS\n"+app.debugDescription)}
}
